	h_{jk} &\leftarrow h_{jk}(1+\theta)\frac{\sum_{i=1}^{I}\left(y_{ij}\frac{s_{ij}+\theta}{s_{ij} + \theta y_{ij}}\cdot\frac{w_{ik}}{s_{ij}}\right)}{\sum_{i=1}^{I}w_{ik}}, 
	\label{update_GPMF1} \\
	\theta &\leftarrow \frac{-\beta+\sqrt{\beta^{2}+4\alpha\gamma}}{2\alpha},
	\label{update_GPMF1_theta}
\end{align}
where
\begin{align*}
	\alpha &= IJ-n_{0}+\sum_{i,j:y_{ij}\ge1}(y_{ij}-1)\eta_{ij1},\\
	\beta  &= \left\{\sum_{i=1}^{I}\sum_{j=1}^{J}(y_{ij}-s_{ij})\right\}-\gamma+\alpha,\\
	\gamma &= \sum_{i,j:y_{ij}\ge1}(y_{ij}-1)\eta_{ij2}.
\end{align*}



\section{Experimental Result}\label{Sec: Experimental Result}
In this section, we evaluate the reconstruction accuracy of PMF, NBMF, and our GPMF using synthetic data. 

The size of the data matrix is set to $I=50$ and $J=100$. The factorization rank, i.e., the number of columns in the two factor matrices, is fixed at $K=5$. Each element of the true basis and coefficient matrices, $W_{0}\in\mathbb{R}_{\ge0}^{I\times K}$ and $H_{0}\in\mathbb{R}_{\ge0}^{J\times K}$, is generated independently from $\mathrm{Gamma}(1.5,1.5)$, where $\mathrm{Gamma}(\theta,\lambda)$ denotes the Gamma distribution with shape $\theta$ and rate $\lambda$. Using these matrices, we compute $S_{0}=W_{0}H_{0}^{\top}$, and then generate the data matrix $Y$ elementwise from a GP as
\[
y_{ij}\sim\mathrm{GP}\left(\dfrac{(S_0)_{ij}}{1+\theta_{0,i}},\dfrac{\theta_{0,i}}{1+\theta_{0,i}}\right).
